import { ADD_USER } from "../types/userTypes";

const initialState = [];

const userReducer = (state = initialState, action) => {
  switch (action.type) {
    case ADD_USER:
      return [...state, 
        {name : action.payload.name.value,
        surname : data.sName.value,
        age: data.age.value}];
    default:
      return state;
  }
};

export default userReducer
